// Cipher for Alice's managed local stores, when a supported cipher is available:
//  - on Alice Desktop and Alice for iOS, the Tauri layer encrypts with a
//    random 32-byte key kept in the operating-system keychain; the key never
//    enters JavaScript (see apps/app-desktop/src-tauri/src/keychain_storage.rs);
//  - in a browser, a non-extractable AES-GCM key generated by WebCrypto and
//    kept in IndexedDB. Non-extractability blocks WebCrypto key export; it
//    does not establish protection of the persisted key or resistance to a
//    complete browser-profile copy. Any script of this origin can use the key.
//    The Android app takes this same path: its webview storage sits in the
//    app's private directory, out of reach of other apps, but the key is not
//    held by the Android Keystore.
// Both produce the same value shape: "v1:" + base64(nonce || ciphertext),
// AES-256-GCM, the storage key bound as additional authenticated data, so a
// value cannot be moved from one key to another.
//
// Where neither is available (no WebCrypto, no IndexedDB) the cipher is
// null and each store decides what to do without one. The same goes for
// Alice Desktop when the keychain cannot give its key (no Secret Service on
// Linux, a keychain left locked, a refused prompt): checkLocalCipher() asks
// once at start, and from a failure on the cipher is null for the session.
// There is never a fallback to a WebCrypto key or a file: both write the
// same "v1:" values, so the values already sealed under the keychain key
// would become unreadable, and nothing is ever written in clear. See
// docs/security/local-chat-encryption.md for the scope and limitations.
//
// The browser key is created once per origin: every tab that finds none
// makes a candidate, and one IndexedDB transaction keeps the first one added,
// so two tabs opening together end up on the same key. A key that is stored
// but cannot be read or used is an error, never a reason to make a new one:
// a new key would leave every value sealed under the old one unreadable.

import type { ChatStorageCipher } from './chat-storage.ts';
import { hasKeychainCipher, isTauriDesktop, tauriInvoke } from './tauri-runtime.ts';

export type LocalCipher = ChatStorageCipher;

export const LOCAL_CIPHER_VERSION = 'v1:';
const NONCE_BYTES = 12;
const KEY_DB = 'alice-local-cipher';
const KEY_STORE = 'keys';
const KEY_ID = 'local-v1';

/** True for a value one of the local ciphers produced. */
export function isLocalCipherValue(value: string): boolean {
  return value.startsWith(LOCAL_CIPHER_VERSION);
}

/** Why Alice Desktop cannot use its keychain key (keychain_storage.rs). */
export type KeychainFailure = 'no-secret-service' | 'locked' | 'denied';
const KEYCHAIN_FAILURES: readonly KeychainFailure[] = ['no-secret-service', 'locked', 'denied'];

/** 'pending' until the desktop check has answered; 'ok' when the device has
 *  a cipher; 'none' when it has none at all (no WebCrypto, no IndexedDB). */
export type LocalCipherStatus = 'pending' | 'ok' | 'none' | KeychainFailure;

/** Thrown by the desktop cipher once the keychain is known to be unavailable. */
export class KeychainUnavailableError extends Error {
  readonly failure: KeychainFailure;

  constructor(failure: KeychainFailure) {
    super(`The system keychain is unavailable (${failure}).`);
    this.name = 'KeychainUnavailableError';
    this.failure = failure;
  }
}

/** By name, so a copy of this module loaded twice still recognizes it. */
export function isKeychainUnavailableError(error: unknown): error is KeychainUnavailableError {
  return error instanceof Error && error.name === 'KeychainUnavailableError';
}

/** The command's rejection, read as one of the three failures. Anything
 *  else (a command that failed to run) counts as a refusal: the key is not
 *  usable either way. */
export function keychainFailureFrom(error: unknown): KeychainFailure {
  const text = typeof error === 'string' ? error : error instanceof Error ? error.message : '';
  return KEYCHAIN_FAILURES.find(failure => failure === text.trim()) ?? 'denied';
}

let keychainCheck: Promise<KeychainFailure | null> | null = null;
let keychainResult: KeychainFailure | null | undefined;
const statusListeners = new Set<() => void>();
function statusChanged(): void {
  for (const listener of statusListeners) {
    try { listener(); } catch { /* one listener cannot stop the others */ }
  }
}

function runKeychainCheck(): Promise<KeychainFailure | null> {
  return tauriInvoke<void>('chat_storage_status').then(() => null, keychainFailureFrom);
}

/**
 * Alice Desktop: asks the shell to load or create the keychain key, once, and
 * resolves with null when it is ready or with the failure. Elsewhere resolves
 * with null at once. Never rejects.
 */
export function checkLocalCipher(): Promise<KeychainFailure | null> {
  if (!isTauriDesktop()) return Promise.resolve(null);
  if (!keychainCheck) {
    keychainCheck = runKeychainCheck().then(failure => {
      keychainResult = failure;
      statusChanged();
      return failure;
    });
  }
  return keychainCheck;
}

/**
 * Asks the keychain again after a failure (the user unlocked it, or started
 * its service). The session stays memory-only meanwhile. On success,
 * `beforeSwitch` runs while the stores still read from memory (to collect
 * what the session kept there), then the cipher comes back and the status
 * listeners hear it; the caller hands what it collected to the stores.
 * Resolves with null on success.
 */
export async function retryLocalCipher(beforeSwitch?: () => Promise<void>): Promise<KeychainFailure | null> {
  if (!isTauriDesktop()) return null;
  const failure = await runKeychainCheck();
  if (!failure && keychainResult && beforeSwitch) await beforeSwitch();
  if (failure !== keychainResult) {
    keychainResult = failure;
    keychainCheck = Promise.resolve(failure);
    statusChanged();
  }
  return failure;
}

/** Where this device stands; see LocalCipherStatus. */
export function localCipherStatus(): LocalCipherStatus {
  if (isTauriDesktop()) return keychainResult === undefined ? 'pending' : keychainResult ?? 'ok';
  return getLocalCipher() ? 'ok' : 'none';
}

export function subscribeLocalCipherStatus(listener: () => void): () => void {
  statusListeners.add(listener);
  return () => { statusListeners.delete(listener); };
}

/** The desktop and iOS cipher: the keychain key, through the Tauri commands.
 *  Each call waits for the start check (Alice Desktop only, iOS has none),
 *  so a value is never sent to the shell before the key is known to be
 *  there, and a keychain that failed is not asked again (one prompt, not one
 *  per value). */
export function createTauriLocalCipher(
  ready: () => Promise<KeychainFailure | null> = checkLocalCipher,
): LocalCipher {
  const keychain = async () => {
    const failure = await ready();
    if (failure) throw new KeychainUnavailableError(failure);
  };
  return {
    encrypt: async (plaintext, context) => {
      await keychain();
      return tauriInvoke<string>('chat_storage_encrypt', { plaintext, context });
    },
    decrypt: async (ciphertext, context) => {
      await keychain();
      return tauriInvoke<string>('chat_storage_decrypt', { ciphertext, context });
    },
  };
}

/** Where a browser keeps its key: IndexedDB, or anything else in tests. */
export interface LocalKeyStore {
  /** The stored key, or null when none was ever stored. Rejects when the
   *  store cannot be read: that is not the same as having no key. */
  get(): Promise<CryptoKey | null>;
  /** Keeps `candidate` only if no key is stored yet, in one atomic step, and
   *  resolves with the key that is stored (the candidate, or the one another
   *  tab added first) once the store has committed. Never replaces a key. */
  getOrAdd(candidate: CryptoKey): Promise<CryptoKey>;
}

/** A stored key is used as it is or not at all. */
function usableKey(value: unknown): CryptoKey {
  const key = value as Partial<CryptoKey> | null | undefined;
  const algorithm = key?.algorithm as { name?: unknown; length?: unknown } | undefined;
  if (
    key && typeof key === 'object' && key.type === 'secret' && algorithm?.name === 'AES-GCM'
    && algorithm.length === 256 && key.extractable === false
    && Array.isArray(key.usages) && key.usages.includes('encrypt') && key.usages.includes('decrypt')
  ) {
    return key as CryptoKey;
  }
  throw new Error('The local key is present but unusable; it is left in place.');
}

function bytesToBase64(bytes: Uint8Array): string {
  let binary = '';
  for (const b of bytes) binary += String.fromCharCode(b);
  return btoa(binary);
}

function base64ToBytes(text: string): Uint8Array {
  const binary = atob(text);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}

/**
 * The browser cipher. `subtle` and `random` are injected so the same code
 * runs under Node's WebCrypto in tests; the key is created on first use,
 * non-extractable, and kept in the key store. A failure to reach the key is
 * retried on the next use, and never leads to a new key.
 */
export function createWebCryptoLocalCipher(
  subtle: SubtleCrypto,
  keyStore: LocalKeyStore,
  random: (bytes: number) => Uint8Array,
): LocalCipher {
  const encoder = new TextEncoder();
  const decoder = new TextDecoder();
  let keyPromise: Promise<CryptoKey> | null = null;
  const key = () => {
    if (!keyPromise) {
      keyPromise = (async () => {
        const stored = await keyStore.get();
        if (stored !== null) return usableKey(stored);
        // None yet. The candidate is made before the store's transaction,
        // which cannot wait on WebCrypto; whichever key the store holds once
        // it commits is the one used, ours or another tab's.
        const candidate = await subtle.generateKey({ name: 'AES-GCM', length: 256 }, false, ['encrypt', 'decrypt']);
        return usableKey(await keyStore.getOrAdd(candidate));
      })().catch(error => { keyPromise = null; throw error; });
    }
    return keyPromise;
  };
  return {
    async encrypt(plaintext, context) {
      // Fresh buffers throughout: WebCrypto wants views over a plain ArrayBuffer.
      const nonce = new Uint8Array(NONCE_BYTES);
      nonce.set(random(NONCE_BYTES));
      const ciphertext = new Uint8Array(await subtle.encrypt(
        { name: 'AES-GCM', iv: nonce, additionalData: encoder.encode(context) },
        await key(),
        encoder.encode(plaintext),
      ));
      const payload = new Uint8Array(nonce.length + ciphertext.length);
      payload.set(nonce, 0);
      payload.set(ciphertext, nonce.length);
      return LOCAL_CIPHER_VERSION + bytesToBase64(payload);
    },
    async decrypt(ciphertext, context) {
      if (!isLocalCipherValue(ciphertext)) throw new Error('Local data is not in a known encrypted form.');
      let payload: Uint8Array;
      try {
        payload = base64ToBytes(ciphertext.slice(LOCAL_CIPHER_VERSION.length));
      } catch {
        throw new Error('Local data could not be decoded.');
      }
      if (payload.length <= NONCE_BYTES) throw new Error('Local data is too short to be authenticated.');
      // Outside the try: a key that cannot be reached is not a forged value.
      const cryptoKey = await key();
      try {
        const plaintext = await subtle.decrypt(
          { name: 'AES-GCM', iv: payload.slice(0, NONCE_BYTES), additionalData: encoder.encode(context) },
          cryptoKey,
          payload.slice(NONCE_BYTES),
        );
        return decoder.decode(plaintext);
      } catch {
        throw new Error('Local data could not be authenticated.');
      }
    },
  };
}

/** The browser's key store: one non-extractable key in IndexedDB. `factory`
 *  is the page's `indexedDB` unless a test hands another. */
export function indexedDbKeyStore(dbName = KEY_DB, factory?: IDBFactory): LocalKeyStore {
  const open = () => new Promise<IDBDatabase>((resolve, reject) => {
    const req = (factory ?? indexedDB).open(dbName, 1);
    req.onupgradeneeded = () => { req.result.createObjectStore(KEY_STORE); };
    let blocked = false;
    req.onsuccess = () => {
      if (blocked) req.result.close();
      else resolve(req.result);
    };
    req.onerror = () => reject(req.error ?? new Error('IndexedDB is unavailable.'));
    req.onblocked = () => { blocked = true; reject(new Error('IndexedDB is blocked.')); };
  });
  // Settles on the transaction, not on its requests: a request can succeed
  // in a transaction that then aborts (quota, a closing database), and then
  // nothing it wrote was kept.
  const transact = <T>(mode: IDBTransactionMode, work: (store: IDBObjectStore, keep: (value: T) => void) => void) =>
    open().then(db => new Promise<T>((resolve, reject) => {
      let kept: { value: T } | null = null;
      let tx: IDBTransaction;
      try {
        tx = db.transaction(KEY_STORE, mode);
      } catch (error) {
        db.close();
        reject(error);
        return;
      }
      tx.oncomplete = () => {
        db.close();
        if (kept) resolve(kept.value);
        else reject(new Error('IndexedDB transaction ended without a result.'));
      };
      tx.onabort = () => { db.close(); reject(tx.error ?? new Error('IndexedDB transaction aborted.')); };
      try {
        work(tx.objectStore(KEY_STORE), value => { kept = { value }; });
      } catch (error) {
        reject(error);
        try { tx.abort(); } catch { /* already over */ }
      }
    }));
  return {
    get: () => transact<CryptoKey | null>('readonly', (store, keep) => {
      const read = store.get(KEY_ID);
      read.onsuccess = () => keep(read.result === undefined ? null : read.result);
    }),
    // The read and the add share one readwrite transaction, and IndexedDB
    // runs those one at a time per store: two tabs cannot both find it empty.
    // `add`, not `put`: even out of turn it fails rather than replace a key.
    getOrAdd: candidate => transact<CryptoKey>('readwrite', (store, keep) => {
      const read = store.get(KEY_ID);
      read.onsuccess = () => {
        if (read.result !== undefined) { keep(read.result); return; }
        const add = store.add(candidate, KEY_ID);
        add.onsuccess = () => keep(candidate);
      };
    }),
  };
}

let memo: LocalCipher | null | undefined;

/**
 * The cipher of this device: the keychain on Alice Desktop and Alice for iOS,
 * WebCrypto in a browser and in the Android app, null where neither exists.
 * Synchronous: the object is ready at once, its key is fetched on first use,
 * so no store ever has to write a value in clear while waiting for it. On
 * Alice Desktop it starts the keychain check, and is null once that check
 * has failed.
 */
export function getLocalCipher(): LocalCipher | null {
  if (isTauriDesktop()) {
    void checkLocalCipher();
    if (keychainResult) return null;
  }
  if (memo !== undefined) return memo;
  if (hasKeychainCipher()) {
    memo = createTauriLocalCipher();
  } else if (typeof indexedDB !== 'undefined' && typeof crypto !== 'undefined' && crypto.subtle) {
    memo = createWebCryptoLocalCipher(crypto.subtle, indexedDbKeyStore(), n => crypto.getRandomValues(new Uint8Array(n)));
  } else {
    memo = null;
  }
  return memo;
}

/** Tests only: forget the memoized cipher and the keychain check. */
export function resetLocalCipherForTests(): void {
  memo = undefined;
  keychainCheck = null;
  keychainResult = undefined;
}
